const app=document.querySelector('#app'),modalRoot=document.querySelector('#modal-root'),loaded=loadWorkspace();
let state=loaded.state,storageMessage=loaded.message,demo=false,view='overview',selectedDate=state.days.at(-1)?.date||today(),selectedPerson='',metricRange='30',plannerMode='timeline',filterPerson='',filterStatus='all',setupDraft=null,setupStep=0,setupEditing=false,modalReturnFocus=null;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const selected=(a,b)=>a===b?' selected':'',checked=v=>v?' checked':'';
const day=()=>state.days.find(d=>d.date===selectedDate),person=id=>state.team.find(p=>p.id===id);
const initials=name=>name.split(/\s+/).map(n=>n[0]).slice(0,2).join('').toUpperCase(),percent=(n,d)=>d?Math.round(n/d*100):0;
const formatDate=(date,options={weekday:'long',month:'long',day:'numeric'})=>new Date(date+'T12:00:00').toLocaleDateString(undefined,options);
const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',planner:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2M14 15h2"/>',tour:'<path d="M9 5H5v16h14V5h-4M9 3h6v4H9zM8 12h8M8 16h5"/>',team:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 4a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 5v2"/>',aisles:'<path d="M4 3v18M20 3v18M4 9h16M4 17h16M8 4v5M15 12v5"/>',routines:'<path d="M20 7a8 8 0 1 0 1 9M20 3v5h-5M12 7v5l3 2"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',check:'<path d="m5 12 4 4L19 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',spark:'<path d="m12 3 2 6 7 3-7 2-2 7-2-7-7-2 7-3z"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',warning:'<path d="m12 3 10 18H2zM12 9v5M12 17h.01"/>'};
const icon=(name,size=19)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.check}</svg>`;
const btn=(text,action,classes='',attrs='')=>`<button class="btn ${classes}" data-action="${action}" ${attrs}>${text}</button>`;
const avatar=(p,small=false)=>`<span class="avatar ${small?'small':''} color-${Math.max(0,state.team.findIndex(x=>x.id===p?.id))%5}" aria-hidden="true">${esc(initials(p?.name||'?'))}</span>`;
const chip=(label,cls='')=>`<span class="chip ${cls}">${esc(label)}</span>`;
const empty=(title,desc,action='')=>`<div class="empty-state"><span class="empty-icon">${icon('planner',30)}</span><h3>${esc(title)}</h3><p>${esc(desc)}</p>${action}</div>`;
const sectionHeader=(title,sub='',action='')=>`<div class="section-heading"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`;
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),5000);}
function commit(mutator,{force=false}={}){const next=structuredClone(state);mutator(next);try{validateState(next);state=demo||loaded.unavailable?next:saveWorkspace(next,{force});storageMessage=loaded.unavailable?'Browser storage is unavailable. This workspace is temporary; export before leaving.':'';render();return true;}catch(error){toast(error.message);return false;}}
function replaceDay(next){return commit(s=>{s.days[s.days.findIndex(d=>d.date===next.date)]=next;});}
function saveDayTask(task){const next=structuredClone(day());next.tasks[next.tasks.findIndex(t=>t.id===task.id)]=task;return replaceDay(next);}
function requireDay(){if(!day()){newDayWizard();return false;}if(day().reviewed){toast('This day has been followed up and is read-only. Start a new day to continue.');return false;}return true;}
function openModal(title,content,wide=false){if(!modalRoot.querySelector('dialog'))modalReturnFocus=document.activeElement;modalRoot.innerHTML=`<dialog class="modal ${wide?'wide':''}" aria-labelledby="modal-title"><div class="modal-heading"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>${content}</dialog>`;const dialog=modalRoot.querySelector('dialog');dialog.showModal();dialog.addEventListener('close',()=>{if(modalRoot.firstElementChild!==dialog)return;modalRoot.innerHTML='';modalReturnFocus?.focus?.();});}
function closeModal(){modalRoot.querySelector('dialog')?.close();}
const errorBox=()=>'<p class="form-error" role="alert"></p>';
function formError(text){const el=modalRoot.querySelector('.form-error')||app.querySelector('.form-error');if(el){el.textContent=text;el.scrollIntoView({block:'nearest'});}else toast(text);}
function deptOptions(value='',all=true){return `${all?'<option value="">All my departments</option>':''}${state.departments.map(d=>`<option value="${esc(d.id)}"${selected(value,d.id)}>D${esc(d.id)} · ${esc(d.name)}</option>`).join('')}`;}
function personOptions(value='',working=false){return `<option value="">Auto-assign</option>${state.team.filter(p=>p.active||p.id===value).filter(p=>!working||day()?.shifts.some(s=>s.personId===p.id)).map(p=>`<option value="${esc(p.id)}"${selected(value,p.id)}>${esc(p.name)}</option>`).join('')}`;}
function daysPicker(name,values){return `<div class="days-picker">${WEEKDAYS.map((d,i)=>`<label><input type="checkbox" name="${name}" value="${i}"${checked(values.includes(i))}><span>${d}</span></label>`).join('')}</div>`;}
function heading(title,description,actions='',eyebrow=''){return `<div class="heading-row"><div class="page-heading">${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`;}
function datePicker(){return `<div class="date-picker"><button data-action="previous-date" aria-label="Previous planned day">‹</button><label><span class="sr-only">Plan date</span><input type="date" id="plan-date" value="${selectedDate}"></label><button data-action="next-date" aria-label="Next planned day">›</button></div>`;}
function render(){
 if(!state.profile){app.innerHTML=welcomeMarkup+(storageMessage?`<div class="recovery-banner">${esc(storageMessage)} ${btn('Restore backup','import')} ${btn('Recover last save','recover')}</div>`:'');return;}
 const titles={overview:'Overview',planner:'Daily planner',tour:'Floor tour',team:'My team',aisles:'Aisles & departments',routines:'Routines & modulars',settings:'Settings'};
 app.innerHTML=`<aside class="sidebar"><a class="brand" href="#overview"><img src="./favicon.svg" alt="">PlanIt<span>TEAM WORKSPACE</span></a><div class="nav-label">WORKSPACE</div><nav aria-label="Main navigation">${Object.entries(titles).filter(([k])=>k!=='settings').map(([key,label])=>`<button data-action="navigate" data-view="${key}" class="${view===key?'active':''}" ${view===key?'aria-current="page"':''}>${icon(key)}<span>${label}</span>${key==='planner'&&day()?`<span class="nav-count">${day().tasks.length}</span>`:''}</button>`).join('')}<button class="mobile-settings" data-action="navigate" data-view="settings">${icon('settings')}<span>Settings</span></button></nav><div class="sidebar-bottom"><div class="privacy-pill">${icon('lock',15)} On this device only</div><button data-action="navigate" data-view="settings" class="settings-nav">${icon('settings')} Settings</button><div class="account">${avatar(person(state.profile.leadId),true)}<div><b>${esc(state.profile.name)}</b><small>Team lead</small></div></div></div></aside><div class="workspace"><header class="topbar"><span>Workspace <b>/ ${titles[view]}</b></span><div class="topbar-right"><span class="local-label">${demo?'Sample workspace':loaded.unavailable?'Temporary workspace':'Saved on this device'} <span class="status-dot"></span></span>${avatar(person(state.profile.leadId),true)}</div></header>${demo?`<div class="demo-banner"><span><b>You’re exploring a sample workspace.</b> These names and results are fictional; changes stay in memory.</span>${btn('Exit sample','exit-demo')}</div>`:''}${storageMessage?`<div class="recovery-banner">${esc(storageMessage)} ${btn('Export current data','export')}</div>`:''}<main id="main" tabindex="-1">${({overview,planner,tour:tourView,team:teamView,aisles:aislesView,routines:routinesView,settings:settingsView})[view]()}</main><footer class="app-footer">PlanIt · Independent planning tool <span>Local data. Clear priorities.</span></footer></div>`;
}
function taskRow(t){const p=person(t.assignedTo);return `<button class="task-row" data-action="edit-task" data-id="${t.id}"><span class="task-status ${t.status==='done'?'done':''}">${t.status==='done'?icon('check',14):''}</span><span class="task-row-body"><b>${esc(t.title)}</b><small>${t.segments.length?clockLabel(t.segments[0].start):'Needs scheduling'} · ${duration(t.minutes)}${t.department?` · D${esc(t.department)}`:''}</small></span>${['urgent','high'].includes(t.priority)?chip(t.priority,'priority-'+t.priority):''}${p?avatar(p,true):chip('Unassigned','amber')}${icon('arrow',16)}</button>`;}
function overview(){
 const d=day(),m=dayMetrics(d),top=topstockProgress(state,selectedDate),weekly=state.days.filter(d=>d.date>=monday(selectedDate)&&d.date<=selectedDate),wm=weekly.flatMap(d=>d.tasks),zones=d?.tasks.filter(t=>t.kind==='zone')||[],needed=d?.tasks.filter(t=>t.status!=='done')||[];
 let html=heading(`Let’s make today count, ${esc(state.profile.name.split(' ')[0])}.`,formatDate(selectedDate),`${datePicker()}${btn(icon('plus')+' New day','new-day')}${btn(icon('tour')+' Conduct tour','conduct-tour','primary')}`,'YOUR TEAM. YOUR PLAN.');
 if(!d)return html+empty('A fresh day starts here','Choose who’s working, set their shifts and meals, and let your routines find their place.',btn('Set up this day '+icon('arrow'),'new-day','primary'));
 if(d.reviewed)html+=`<div class="notice">${icon('check')} Follow-up completed. This day is saved for your records. ${btn('Plan a new day','new-day')}</div>`;
 html+=`<div class="stats-grid"><article class="stat-card"><div class="stat-label">Tasks completed ${icon('check')}</div><div class="stat-value">${m.done}<span>/ ${m.total}</span></div><div class="progress-track"><span style="width:${m.percent}%"></span></div><small>${m.percent}% of the day’s tasks</small></article><article class="stat-card"><div class="stat-label">On the floor today ${icon('team')}</div><div class="stat-value">${d.shifts.length}<span>people</span></div><div class="avatar-stack">${d.shifts.map(s=>avatar(person(s.personId),true)).join('')}<small>${duration(m.capacity)} after breaks</small></div></article><article class="stat-card"><div class="stat-label">Weekly top stock ${icon('aisles')}</div><div class="stat-value">${top.done}<span>/ ${top.total} aisles</span></div><div class="progress-track blue"><span style="width:${percent(top.done,top.total)}%"></span></div><small>${top.remaining.length?`${top.remaining.length} aisles to finish by Friday`:'All eligible aisles complete'}</small></article><article class="stat-card ${m.unassigned?'attention':''}"><div class="stat-label">Needs attention ${icon('warning')}</div><div class="stat-value">${m.unassigned}<span>tasks</span></div><small>${m.unassigned?'Work that needs capacity or reassignment':'All tasks have a place in the plan'}</small>${btn('Review the plan '+icon('arrow',14),'navigate','text-link','data-view="planner"')}</article></div>`;
 html+=`<div class="dashboard-grid"><section class="card focus-card">${sectionHeader('Today’s focus',`${needed.length} tasks left to move the day forward.`,btn('View planner '+icon('arrow',15),'navigate','text-link','data-view="planner"'))}${needed.length?needed.sort((a,b)=>Number(!!a.assignedTo)-Number(!!b.assignedTo)||(a.segments[0]?.start||0)-(b.segments[0]?.start||0)).slice(0,6).map(taskRow).join(''):empty('A day well done','Everything on this plan has been completed.')}</section><section class="card week-card">${sectionHeader('A little better, every day','Task completion this week')}<div class="week-chart" role="img" aria-label="Daily task completion percentages">${Array.from({length:7},(_,i)=>{const date=addDays(monday(selectedDate),i),dm=dayMetrics(state.days.find(d=>d.date===date));return `<div class="chart-column"><span>${dm.total?dm.percent+'%':'—'}</span><div class="bar-well"><i style="height:${dm.percent}%;${date===selectedDate?'background:#1c5441':''}"></i></div><b class="${date===selectedDate?'today':''}">${WEEKDAYS[(i+1)%7]}</b></div>`;}).join('')}</div><div class="week-summary"><b>${wm.filter(t=>t.status==='done').length} tasks completed</b><span>Across ${weekly.length} planned days</span></div></section></div>`;
 const notZoned=state.aisles.filter(a=>!lastAisleWork(state,a.id,'zone',addDays(selectedDate,1))).length;
 return html+`<div class="dashboard-grid lower"><section class="card">${sectionHeader('Your team’s capacity','A balanced plan leaves room for the unexpected.')}<div class="capacity-list">${d.shifts.map(s=>{const p=person(s.personId),tasks=d.tasks.filter(t=>t.assignedTo===s.personId),scheduled=tasks.flatMap(t=>t.segments).reduce((n,t)=>n+t.end-t.start,0),cap=capacity(s);return `<button class="capacity-row" data-action="profile" data-id="${esc(s.personId)}">${avatar(p,true)}<span class="capacity-name"><b>${esc(p?.name||'Associate')}</b><small>${clockLabel(s.start)} – ${clockLabel(shiftBounds(s).end)}</small></span><span class="capacity-bar"><i style="width:${Math.min(100,percent(scheduled,cap))}%"></i></span><span class="capacity-numbers">${duration(scheduled)} / ${duration(cap)}<small>${tasks.filter(t=>t.status==='done').length} of ${tasks.length} done</small></span></button>`;}).join('')}</div></section><section class="card opportunity-card">${sectionHeader('Room to improve','Small signals for your next floor walk.')}<div class="insight"><span class="insight-symbol">01</span><div><b>${notZoned?`${notZoned} aisles without a completed zone`:'Every aisle has zoning history'}</b><p>${notZoned?'Start with the aisles you haven’t reached. Tour priorities take their place in the plan.':'Older zones are automatically prioritized next time.'}</p></div></div><div class="insight"><span class="insight-symbol">02</span><div><b>${d.tasks.filter(t=>t.source==='carry').length} tasks carried into this day</b><p>Check estimates and shift time when the same work keeps coming back.</p></div></div><div class="insight"><span class="insight-symbol">03</span><div><b>${duration(Math.max(0,m.capacity-m.scheduled))} of unallocated shift time</b><p>${zones.length} zoning assignments planned. Meals and rest breaks are reserved.</p></div></div></section></div>`;
}
function planner(){
 const d=day(),m=dayMetrics(d);let html=heading('A place for everything.',`${formatDate(selectedDate)} · ${d?duration(m.scheduled)+' scheduled · '+duration(m.capacity)+' available':'Set up a day to build the plan.'}`,`${datePicker()}${btn(icon('plus')+' Add task','add-task')}${btn(icon('spark')+' Rebalance','rebalance','primary')}`);
 if(!d)return html+empty('Your planner is ready when you are','Add shifts and meals to start assigning work.',btn('Set up day','new-day','primary'));
 const unscheduled=d.tasks.filter(t=>t.status!=='done'&&!t.segments.length);
 if(unscheduled.length)html+=`<div class="notice amber">${icon('warning')} <span><b>${unscheduled.length} tasks need scheduling.</b> Adjust shifts, assign another person, or carry them forward at follow-up.</span></div>`;
 if(d.reviewed)html+=`<div class="notice">${icon('lock')} This day is followed up and read-only.</div>`;
 html+=`<div class="planner-toolbar"><div class="segmented"><button data-action="planner-mode" data-mode="timeline" class="${plannerMode==='timeline'?'active':''}">${icon('planner',16)} Timeline</button><button data-action="planner-mode" data-mode="list" class="${plannerMode==='list'?'active':''}">List view</button></div><div class="filters"><label class="sr-only" for="person-filter">Filter by person</label><select id="person-filter"><option value="">Everyone</option>${d.shifts.map(s=>`<option value="${s.personId}"${selected(filterPerson,s.personId)}>${esc(person(s.personId)?.name)}</option>`).join('')}</select><label class="sr-only" for="status-filter">Filter by status</label><select id="status-filter"><option value="all"${selected(filterStatus,'all')}>All tasks</option><option value="pending"${selected(filterStatus,'pending')}>To do</option><option value="in-progress"${selected(filterStatus,'in-progress')}>In progress</option><option value="done"${selected(filterStatus,'done')}>Completed</option></select>${btn('Edit shifts','edit-shifts')}${btn('Follow up','follow-up')}</div></div>`;
 const filter=t=>(!filterPerson||t.assignedTo===filterPerson)&&(filterStatus==='all'||t.status===filterStatus);
 if(plannerMode==='list'){const tasks=d.tasks.filter(filter).sort((a,b)=>(a.segments[0]?.start??3000)-(b.segments[0]?.start??3000));return html+`<section class="card">${tasks.length?tasks.map(taskRow).join(''):empty('No matching tasks','Try another filter or add a task.')}</section>`;}
 const shifts=d.shifts.filter(s=>!filterPerson||s.personId===filterPerson),start=Math.floor(Math.min(...d.shifts.map(s=>s.start))/60)*60,end=Math.ceil(Math.max(...d.shifts.map(s=>shiftBounds(s).end))/60)*60,unit=2.4;
 html+=`<div class="timeline-scroller"><div class="timeline" style="--cols:${shifts.length};--timeline-height:${(end-start)*unit}px"><div class="timeline-head time-head">TIME</div>${shifts.map(s=>`<div class="timeline-head">${avatar(person(s.personId),true)}<div><b>${esc(person(s.personId)?.name)}</b><small>${clockLabel(s.start)} – ${clockLabel(shiftBounds(s).end)}</small></div><span>${d.tasks.filter(t=>t.assignedTo===s.personId).length} tasks</span></div>`).join('')}<div class="time-axis" style="height:${(end-start)*unit}px">${Array.from({length:(end-start)/60},(_,i)=>`<span style="top:${i*60*unit}px">${clockLabel(start+i*60)}</span>`).join('')}</div>${shifts.map(s=>`<div class="person-lane" data-person="${s.personId}" data-start="${start}" style="height:${(end-start)*unit}px;background-size:100% ${60*unit}px">${pauses(s).map(p=>`<div class="break-block ${p.meal?'meal':''}" style="top:${(p.start-start)*unit}px;height:${(p.end-p.start)*unit}px"><span>${p.meal?'Meal break':'Rest break'} · ${duration(p.end-p.start)}</span></div>`).join('')}${d.tasks.filter(t=>t.assignedTo===s.personId&&filter(t)).flatMap(t=>t.segments.map((seg,i)=>`<button class="schedule-task ${seg.end-seg.start<20?'compact':'full-block'} task-${t.kind} ${t.status==='done'?'completed':''}" data-action="edit-task" data-id="${t.id}" draggable="${!d.reviewed&&t.status!=='done'}" data-task="${t.id}" style="top:${(seg.start-start)*unit}px;height:${Math.max(25,(seg.end-seg.start)*unit-3)}px" title="${esc(t.title)} · ${clockLabel(seg.start)}–${clockLabel(seg.end)}${t.locked?' · Pinned':''}"><span class="task-time">${clockLabel(seg.start)} · ${duration(seg.end-seg.start)} ${t.status==='done'?'✓':t.locked?'⌑':''}</span><b>${esc(t.title)}</b>${(seg.end-seg.start)>=40?`<span>${t.source==='tour'?'Floor tour':t.source==='carry'?'Carried forward':t.kind==='zone'?'Aisle care':t.source==='routine'?'Routine':'Task'}${t.department?' · D'+esc(t.department):''}${t.segments.length>1?' · Part '+(i+1):''}</span>`:''}</button>`)).join('')}</div>`).join('')}</div></div><div class="planner-legend"><span><i class="legend-green"></i> Routine</span><span><i class="legend-blue"></i> Top stock</span><span><i class="legend-purple"></i> Zoning</span><span><i class="legend-amber"></i> Tour / custom</span><small>Click to edit. Drag to an open time to pin. Use task details on touch devices.</small></div>`;
 if(unscheduled.length)html+=`<section class="card backlog">${sectionHeader('Unscheduled work','These tasks carry forward if unfinished.')}${unscheduled.filter(filter).map(taskRow).join('')}</section>`;return html;
}
function tourView(){
 const d=day();let html=heading('See it. Note it. Plan it.','Capture priorities while you walk. Complete your tour to make room for them in the day.',btn(icon('check')+' Complete tour','complete-tour','primary'));
 if(!d||d.reviewed)return html+empty(d?'This tour is saved':'Set up your day first','The tour needs your team’s shifts to assign the work.',btn('Set up day','new-day','primary'));
 return html+`<div class="tour-layout"><section class="card tour-compose">${sectionHeader('A new observation','Add a note or prioritize an aisle for zoning.')}<form id="tour-form"><label>What needs attention?<textarea name="title" rows="3" required maxlength="300" placeholder="e.g. Refresh the cookware endcap"></textarea></label><div class="form-grid"><label>Type<select name="kind"><option value="custom">Task / observation</option><option value="zone">Zone an aisle</option></select></label><label>Priority<select name="priority"><option value="normal">Normal</option><option value="high">High</option><option value="urgent">Urgent</option><option value="low">Low</option></select></label><label>Department<select name="department">${deptOptions()}</select></label><label>Aisle<select name="aisleId"><option value="">No specific aisle</option>${state.aisles.map(a=>`<option value="${a.id}">${esc(a.label)} · D${esc(a.department)}</option>`).join('')}</select></label><label>Estimate (minutes)<input type="number" name="minutes" value="20" min="5" max="960" step="5" required></label><label>Assign to<select name="assignee">${personOptions('',true)}</select></label></div><label>Additional notes<textarea name="notes" rows="2" maxlength="5000" placeholder="Helpful context for whoever picks this up"></textarea></label><p class="helper">Zoning notes use your zoning window and replace that aisle’s automatic assignment. In-progress and completed work stays in place.</p>${errorBox()}<button class="btn primary full" type="submit">${icon('plus')} Add to tour</button></form></section><section class="card">${sectionHeader('On this tour',`${state.tourDraft.length} observations ready to integrate`,chip('DRAFT','gray'))}${state.tourDraft.length?state.tourDraft.map(t=>`<div class="tour-note"><div class="tour-note-top">${chip(t.priority,'priority-'+t.priority)}<button data-action="remove-note" data-id="${t.id}" class="icon-btn" aria-label="Remove note ${esc(t.title)}">${icon('close',16)}</button></div><h3>${esc(t.title)}</h3><p>${esc(t.notes)}</p><div class="note-meta">${t.kind==='zone'?'Zoning · ':''}${t.department?'D'+esc(t.department)+' · ':''}${duration(t.minutes)} · ${esc(person(t.assignee)?.name||'Auto-assign')}</div></div>`).join(''):empty('Eyes on the floor','Your observations appear here as you add them. Drafts are saved on this device.')}${d.tour.length?`<details class="tour-history"><summary>${d.tour.length} observations already integrated today</summary>${d.tour.map(t=>`<p>${esc(t.title)}</p>`).join('')}</details>`:''}</section></div>`;
}
function metricPeriod(){return metricRange==='all'?{from:'',to:selectedDate}:{from:addDays(selectedDate,-Number(metricRange)+1),to:selectedDate};}
function teamView(){
 const range=metricPeriod();let html=heading(selectedPerson?esc(person(selectedPerson)?.name||'Associate'):'Good plans start with people.','Completion, capacity, and aisle care — built from what you record.',`<label class="sr-only" for="metric-range">Metrics period</label><select id="metric-range"><option value="7"${selected(metricRange,'7')}>Last 7 days</option><option value="30"${selected(metricRange,'30')}>Last 30 days</option><option value="all"${selected(metricRange,'all')}>All history</option></select>${btn(icon('plus')+' Add associate','add-person')}`);
 html+=`<p class="metrics-context">Through ${formatDate(selectedDate,{month:'short',day:'numeric',year:'numeric'})}. Zoning completion averages recorded progress across assigned zones; carried attempts count separately.</p>`;
 if(selectedPerson){const p=person(selectedPerson),m=personMetrics(state,selectedPerson,range.from,range.to),tasks=state.days.filter(d=>d.date>=range.from&&d.date<=range.to).flatMap(d=>d.tasks.filter(t=>t.assignedTo===p.id).map(t=>({...t,date:d.date})));
 return html+`${btn('‹ Back to team','back-team','text-link')}<section class="profile-header card">${avatar(p)}<div><h2>${esc(p.name)}</h2><p>${esc(p.role)} · ${p.active?'Active':'Archived'} · ${p.departments.length?p.departments.map(id=>'D'+esc(id)).join(', '):'All your departments'}</p></div>${btn('Edit profile','edit-person','','data-id="'+p.id+'"')}</section><div class="stats-grid">${[['Task completion',m.completion===null?'—':m.completion+'%',`${m.done} of ${m.tasks} tasks`],['Average zoning completion',m.zone===null?'—':m.zone+'%',`${m.zones} assigned zones`],['Top stock completed',m.topstock,`${m.shifts} recorded shifts`],['Actual / estimated time',m.actualRatio===null?'—':m.actualRatio+'%',`${m.timed} tasks with actual time`]].map(([label,value,note])=>`<article class="stat-card"><div class="stat-label">${label}</div><div class="stat-value">${value}</div><small>${note}</small></article>`).join('')}</div><section class="card">${sectionHeader('Recent work',`${m.carry} carried attempts · ${duration(m.plannedMinutes)} estimated work`)}${tasks.length?`<div class="table-scroll"><table><thead><tr><th>Task</th><th>Day</th><th>Planned</th><th>Actual</th><th>Completion</th></tr></thead><tbody>${tasks.reverse().slice(0,100).map(t=>`<tr><td>${esc(t.title)}</td><td>${formatDate(t.date,{month:'short',day:'numeric'})}</td><td>${duration(t.minutes)}</td><td>${t.actualMinutes?duration(t.actualMinutes):'—'}</td><td>${chip(t.status==='done'?'Complete':t.progress+'%',t.status==='done'?'green':'gray')}</td></tr>`).join('')}</tbody></table></div>`:empty('No work recorded yet','Assigned tasks will build this profile over time.')}</section>`;}
 return html+`<div class="team-grid">${state.team.map(p=>{const m=personMetrics(state,p.id,range.from,range.to);return `<button class="card person-card" data-action="profile" data-id="${p.id}"><div class="person-card-top">${avatar(p)}${chip(p.active?p.role:'Archived',p.role==='Team lead'?'green':'gray')}</div><h2>${esc(p.name)}</h2><p>${m.shifts} shifts · ${m.tasks} assigned tasks</p><div class="person-stat"><span>Task completion</span><b>${m.completion===null?'—':m.completion+'%'}</b></div><div class="progress-track"><span style="width:${m.completion||0}%"></span></div><div class="person-stat"><span>Average zoning</span><b>${m.zone===null?'—':m.zone+'%'}</b></div><div class="progress-track purple"><span style="width:${m.zone||0}%"></span></div><div class="person-card-footer">View profile ${icon('arrow',17)}</div></button>`;}).join('')}</div>`;
}
function aislesView(){const top=topstockProgress(state,selectedDate);return heading('Know your floor.','Your departments, aisle coverage, and the work behind a well-kept zone.',btn('Edit workspace','edit-workspace'))+`<div class="aisle-summary"><span>${state.departments.length} departments</span><span>${state.aisles.length} aisles</span><span>${top.total} with top stock</span><span>${top.done} top-stock aisles completed this week</span></div>${state.departments.map(d=>{const aisles=state.aisles.filter(a=>a.department===d.id);return `<section class="card department-card">${sectionHeader(`<span class="department-number">${esc(d.id)}</span> ${esc(d.name)}`,`${aisles.length} aisles · ${state.settings.rfid[d.id]?.enabled?'RFID '+state.settings.rfid[d.id].days.map(n=>WEEKDAYS[n]).join(', '):'Tuesday deep outs when enabled'}`,btn(icon('plus')+' Add aisle','add-aisle','','data-department="'+esc(d.id)+'"'))}${aisles.length?`<div class="aisle-grid">${aisles.map(a=>{const last=lastAisleWork(state,a.id,'zone',addDays(selectedDate,1)),done=!top.remaining.some(x=>x.id===a.id);return `<button class="aisle-tile ${a.topstock&&done?'top-done':''}" data-action="edit-aisle" data-id="${a.id}"><div><b>${esc(a.label)}</b>${a.topstock?`<span title="Top stock">${icon('aisles',16)} ${done?'✓':''}</span>`:''}</div><p>${last?'Zoned '+formatDate(last,{month:'short',day:'numeric'}):'No completed zone yet'}</p><small>Zone ${duration(a.zoneMinutes)}${a.topstock?' · Top stock '+duration(a.topMinutes):''}</small></button>`;}).join('')}</div>`:empty('Map this department','Add aisle labels and tick the ones with top stock.')}</section>`;}).join('')}`;}
function routinesView(){return heading('Build your everyday rhythm.','Turn on the routines you use. Adjust estimates to fit your store.',btn(icon('plus')+' Repeating task','add-repeat','primary'))+`<div class="notice">${icon('clock')} <span>Editable planning defaults, not verified company time standards. Changes apply to new days; refresh pending routines below to use them today.</span>${btn('Apply to current day','apply-routines')}</div><section class="card">${sectionHeader('Routine library','The recurring work that keeps your departments moving.')}<div class="routine-grid">${ROUTINES.map(r=>{const cfg=state.settings.routines[r.id];return `<div class="routine-item"><div class="routine-icon">${icon(['zone','topstock'].includes(r.id)?'aisles':'routines')}</div><div class="routine-description"><b>${r.name}</b><p>${r.description}</p><button class="text-link" data-action="configure-routine" data-id="${r.id}">${['topstock','zone'].includes(r.id)?'Aisle estimates':duration(cfg.minutes)} · Configure ${icon('arrow',13)}</button></div><label class="switch"><input type="checkbox" data-routine-toggle="${r.id}"${checked(cfg.enabled)} aria-label="Enable ${r.name}"><span></span></label></div>`;}).join('')}</div></section><section class="card section-gap">${sectionHeader('Repeating tasks','Your own routines, on the days you choose.',btn('Add task','add-repeat'))}${state.repeats.length?state.repeats.map(r=>`<div class="library-row"><div><b>${esc(r.title)}</b><small>${r.days.map(d=>WEEKDAYS[d]).join(', ')} · ${duration(r.minutes)} · ${r.active?'Active':'Paused'}</small></div>${btn('Edit','edit-repeat','','data-id="'+r.id+'"')}</div>`).join(''):empty('Make room for your routines','Add weekly checks, recurring projects, or other work your team owns.')}</section><section class="card section-gap">${sectionHeader('Modular categories','Due or undated categories join new plans when Modulars is enabled.',btn(icon('plus')+' Add modular','add-modular'))}${state.modulars.length?`<div class="table-scroll"><table><thead><tr><th>Category</th><th>Department</th><th>Sections</th><th>Estimate</th><th>Due / status</th><th></th></tr></thead><tbody>${state.modulars.map(m=>`<tr><td><b>${esc(m.category)}</b><small>${esc(m.description)}</small></td><td>D${esc(m.department)}</td><td>${m.sections}</td><td>${duration(m.minutes)}</td><td>${m.completed?chip('Complete','green'):esc(m.dueDate||'Next plan')}</td><td>${btn('Edit','edit-modular','','data-id="'+m.id+'"')}</td></tr>`).join('')}</tbody></table></div>`:empty('A home for your next reset','Track the department, category number, sections, and completion estimate.')}</section>`;}
function settingsView(){return heading('Your workspace, your way.','Manage your setup and the information saved on this device.')+`<div class="settings-layout"><section class="card">${sectionHeader('Workspace')}<div class="library-row"><div><b>Floor map & aisle history</b><small>See zoning recency and weekly top-stock coverage.</small></div>${btn('View aisles','navigate','','data-view="aisles"')}</div><div class="library-row"><div><b>${esc(state.profile.name)}’s workspace</b><small>${state.departments.length} departments · ${state.aisles.length} aisles · ${state.team.filter(p=>p.active).length} active people</small></div>${btn('Edit setup','edit-workspace')}</div><div class="library-row"><div><b>Planning defaults</b><small>Routine estimates, scan days, reshop windows, and zoning.</small></div>${btn('Manage routines','navigate','','data-view="routines"')}</div><div class="library-row"><div><b>Sample workspace</b><small>Try the planner with fictional data, separate from your saved work.</small></div>${btn('Explore sample','demo')}</div></section><section class="card">${sectionHeader('Local data & backups','Names, shifts, notes, and metrics are stored in this browser on this device.')}<p>PlanIt has no account, analytics, cloud database, or Walmart system connection. Clearing site data or changing browsers removes access to this workspace. Anyone with access to this browser profile may be able to view it.</p><p class="helper">A downloaded backup contains your personal planning data. Keep it somewhere private. GitHub receives normal page requests, but the app never sends your workspace data to GitHub or other services.</p><div class="button-row">${btn(icon('download')+' Export backup','export','primary')}${btn('Restore backup','import')}${btn('Recover last save','recover')}</div><div class="divider"></div>${btn('Erase this workspace','reset','danger')}</section></div><section class="card section-gap">${sectionHeader('Public references & planning assumptions','References checked September 13, 2026. Department names can be customized for your store.')}<p class="helper">Tuesday deep outs, Friday top-stock coverage, daily Pinpoint, and other routine timings are the requested planning rules, not verified universal Walmart policy. Check your current store guidance. You enter meal and rest-break times; PlanIt does not enforce employment rules.</p><div class="reference-grid">${SOURCES.map(s=>`<a class="reference" href="${s.url}" target="_blank" rel="noopener noreferrer"><b>${s.title} ↗</b><small>${s.publisher}</small><p>${s.note}</p></a>`).join('')}</div><p class="helper">PlanIt is independently made and is not affiliated with or endorsed by Walmart.</p></section>`;}
